"use client";

import "./badge.css";

import type React from "react";

import { cn } from "tailwind-variants";

import { BadgeContext } from "./badge.context";
import { badgeVariants, type BadgeVariants } from "./badge.variants";

export type BadgeProps = BadgeVariants & React.HTMLAttributes<HTMLDivElement>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/badge/content.md
 */
export const BadgeRoot = ({ children, className, variant, size, ...props }: BadgeProps) => {
  const slots = badgeVariants({ variant, size });

  return (
    <BadgeContext.Provider value={{ slots }}>
      <div className={cn(slots.root(), className)} {...props}>
        {children}
      </div>
    </BadgeContext.Provider>
  );
};

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/badge/content.md
 */
export const Badge = BadgeRoot;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const badgeVariants = tv({
  slots: {
    root: "badge",
  },
  variants: {
    variant: {
      default: {
        root: "bg-primary text-primary-foreground hover:bg-primary/80 border-transparent",
      },
      secondary: {
        root: "bg-secondary text-secondary-foreground hover:bg-secondary/80 border-transparent",
      },
      destructive: {
        root: "bg-destructive text-destructive-foreground hover:bg-destructive/80 border-transparent",
      },
      outline: {
        root: "text-foreground border-border bg-background hover:bg-accent hover:text-accent-foreground",
      },
    },
    size: {
      sm: {
        root: "px-2 py-0.5 text-xs font-semibold",
      },
      md: {
        root: "px-2.5 py-0.5 text-xs font-semibold",
      },
      lg: {
        root: "px-3 py-1 text-sm font-semibold",
      },
    },
  },
  defaultVariants: {
    variant: "default",
    size: "md",
  },
});

export type BadgeVariants = VariantProps<typeof badgeVariants>;

"use client";

import { createContext, useContext } from "react";

import { badgeVariants } from "./badge.variants";

export type BadgeContext = {
  slots: ReturnType<typeof badgeVariants>;
};

export const BadgeContext = createContext<BadgeContext | null>(null);

export const useBadgeContext = () => {
  const context = useContext(BadgeContext);
  return context ?? { slots: badgeVariants() };
};

.badge {
  @apply inline-flex items-center rounded-full border transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 select-none;
}

import { Badge, BadgeRoot } from "./badge";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/badge/content.md
 */
export const BadgeContainer = {
  Root: BadgeRoot,
};

export { Badge, BadgeRoot };

export type { BadgeProps } from "./badge";
export { BadgeContext, useBadgeContext } from "./badge.context";
export { type BadgeVariants, badgeVariants } from "./badge.variants";
